  "2c624dee-4767-581b-a92f-2b9856a9eff7": {
    "source": {
      "name": "Kurczak pieczony z warzywami",
      "description": "Jednogarnkowy obiad prosto z piekarnika.",
      "instructions": [
        "Nagrzej piekarnik do 200°C.",
        "Pokrój ziemniaki (500 g) i marchew (300 g) w kawałki, wymieszaj z olejem, solą i pieprzem.",
        "Ułóż warzywa i kurczaka (600 g) na blasze, skrop oliwą (30 ml) i dopraw.",
        "Piecz 35-40 minut, aż kurczak i warzywa się zarumienią.",
      ],
      "suggested_seasonings": ["tymianek", "rozmaryn", "papryka wędzona"],
    },
    "en_GB": {
      "name": "Roast chicken with vegetables",
      "description": "A one-pot lunch straight from the oven.",
      "instructions": [
        "Preheat the oven to 200°C.",
        "Cut the potatoes (500 g) and carrots (300 g) into pieces, then toss with oil, salt and pepper.",
        "Arrange the vegetables and chicken (600 g) on a baking tray, drizzle with olive oil (30 ml) and season.",
        "Bake for 35-40 minutes until the chicken and vegetables are golden.",
      ],
      "suggested_seasonings": ["thyme", "rosemary", "smoked paprika"],
    },
  },
  "53a5a6cd-e9ab-5f31-a5bf-822e66dc1e7b": {
    "source": {
      "name": "Dorsz pieczony z cytryną i ziołami",
      "description": "Lekki obiad rybny — gotowy w pół godziny.",
      "instructions": [
        "Nagrzej piekarnik do 190°C.",
        "Ułóż filety dorsza (400 g) na blasze, skrop oliwą (15 ml) i sokiem z cytryny (1 szt.).",
        "Posyp oregano (2 g), solą i pieprzem.",
        "Piecz 15-18 minut, aż ryba będzie biała i łatwo się rozdzieli widelcem.",
      ],
      "suggested_seasonings": ["koperek", "tymianek"],
    },
    "en_GB": {
      "name": "Cod baked with lemon and herbs",
      "description": "A light fish lunch — ready in half an hour.",
      "instructions": [
        "Preheat the oven to 190°C.",
        "Place the cod fillets (400 g) on a baking tray and drizzle with olive oil (15 ml) and lemon juice (1 lemon).",
        "Sprinkle with oregano (2 g), salt and pepper.",
        "Bake for 15-18 minutes until the fish is white and flakes easily with a fork.",
      ],
      "suggested_seasonings": ["dill", "thyme"],
    },
  },
  "fc5ee50f-1091-5f4b-a80a-a28a3f1bf4de": {
    "source": {
      "name": "Krewetki curry z ryżem",
      "description": "Szybkie, aromatyczne danie w azjatyckim stylu.",
      "instructions": [
        "Jeśli krewetki (250 g) są mrożone, rozmroź je wcześniej w lodówce lub pod zimną wodą — nie gotuj mrożonych.",
        "Ugotuj ryż (150 g) według instrukcji na opakowaniu.",
        "Rozgrzej odrobinę oleju na patelni, wsyp curry (8 g) i smaż mieszając ok. 30-60 sekund, aż zapachnie.",
        "Wlej mleko kokosowe (200 ml), wymieszaj z przyprawą i zagotuj.",
        "Dodaj krewetki i gotuj 4-5 minut — są gotowe, gdy zrobią się różowo-nieprzezroczyste i lekko zawiną (dłuższe gotowanie je usztywni).",
        "Podawaj curry z krewetkami na ugotowanym ryżu.",
      ],
      "suggested_seasonings": ["kolendra świeża", "chili w płatkach"],
    },
    "en_GB": {
      "name": "Prawn curry with rice",
      "description": "A quick, fragrant Asian-style dish.",
      "instructions": [
        "If the prawns (250 g) are frozen, thaw them beforehand in the fridge or under cold water. Do not cook from frozen.",
        "Cook the rice (150 g) according to the packet instructions.",
        "Heat a little oil in a frying pan, add the curry powder (8 g) and fry, stirring, for about 30-60 seconds until fragrant.",
        "Pour in the coconut milk (200 ml), stir into the spice and bring to the boil.",
        "Add the prawns and cook for 4-5 minutes. They are ready when pink, opaque and slightly curled; cooking longer will toughen them.",
        "Serve the prawn curry over the cooked rice.",
      ],
      "suggested_seasonings": ["fresh coriander", "chilli flakes"],
    },
  },
  "783dba78-6154-5291-99ea-a5202445a6e9": {
    "source": {
      "name": "Placki ziemniaczane",
      "description": "Chrupiące placki, klasyka polskiej kuchni.",
      "instructions": [
        "Zetrzyj ziemniaki (800 g) i cebulę na drobnej tarce, odciśnij nadmiar wody.",
        "Dodaj jajko (1 szt.) i mąkę, dopraw solą, wymieszaj.",
        "Smaż placki na rozgrzanym oleju po 3-4 minuty z każdej strony.",
        "Podawaj ze śmietaną lub jogurtem.",
      ],
      "suggested_seasonings": ["gałka muszkatołowa", "majeranek"],
    },
    "en_GB": {
      "name": "Potato pancakes",
      "description": "Crisp pancakes, a Polish classic.",
      "instructions": [
        "Finely grate the potatoes (800 g) and onion, then squeeze out excess water.",
        "Add the egg (1 egg) and flour, season with salt and mix.",
        "Fry the pancakes in hot oil for 3-4 minutes on each side.",
        "Serve with cream or yoghurt.",
      ],
      "suggested_seasonings": ["nutmeg", "marjoram"],
    },
  },
  "a2c91d72-d3e9-59d8-b78f-db9b472481b6": {
    "source": {
      "name": "Bigos szybki",
      "description":
          "Uproszczona wersja klasycznego bigosu na obiad w tydzień.",
      "instructions": [
        "Kiełbasę (300 g) pokrój w plastry grubości ok. 1 cm, cebulę (150 g) w kostkę.",
        "Rozgrzej garnek z grubym dnem, podsmaż kiełbasę i cebulę razem 5-6 minut, aż kiełbasa lekko się zarumieni.",
        "Kapustę (1 szt.) poszatkuj na cienkie paski.",
        "Dodaj kapustę do garnka razem z pomidorami krojonymi (400 g), dokładnie wymieszaj.",
        "Przykryj i duś na małym ogniu 30-35 minut, mieszając co jakiś czas, żeby kapusta nie przywarła do dna.",
        "Dopraw solą, pieprzem i odrobiną papryki słodkiej, wymieszaj i spróbuj przed podaniem.",
      ],
      "suggested_seasonings": [
        "liść laurowy",
        "ziele angielskie",
        "kminek",
        "majeranek",
      ],
    },
    "en_GB": {
      "name": "Quick bigos",
      "description":
          "A simplified version of classic bigos for a weekday lunch.",
      "instructions": [
        "Slice the sausage (300 g) about 1 cm thick and dice the onion (150 g).",
        "Heat a heavy-based saucepan and fry the sausage and onion together for 5-6 minutes until the sausage is lightly browned.",
        "Shred the cabbage (1 cabbage) into thin strips.",
        "Add the cabbage to the saucepan with the chopped tomatoes (400 g) and stir thoroughly.",
        "Cover and simmer over a low heat for 30-35 minutes, stirring occasionally to prevent the cabbage sticking.",
        "Season with salt, pepper and a little sweet paprika, stir and taste before serving.",
      ],
      "suggested_seasonings": ["bay leaf", "allspice", "caraway", "marjoram"],
    },
  },
  "efe248e8-006a-5550-8f37-50f052e6c3f2": {
    "source": {
      "name": "Pierogi leniwe",
      "description": "Twarogowe kluski — szybsze niż tradycyjne pierogi.",
      "instructions": [
        "Rozgnieć twaróg (500 g) z jajkami, dodaj mąkę (150 g) i zagnieć na jednolite ciasto.",
        "Uformuj wałeczek, pokrój na kawałki i uformuj kluski.",
        "Gotuj we wrzącej, osolonej wodzie, aż wypłyną (ok. 3-4 minuty).",
        "Polej roztopionym masłem (20 g) i podawaj.",
      ],
      "suggested_seasonings": ["wanilia", "cynamon"],
    },
    "en_GB": {
      "name": "Lazy quark dumplings",
      "description": "Quark dumplings — quicker than traditional pierogi.",
      "instructions": [
        "Mash the quark (500 g) with the eggs, add the flour (150 g) and knead into a uniform dough.",
        "Shape into a log, cut into pieces and form dumplings.",
        "Cook in boiling salted water until they float to the surface, about 3-4 minutes.",
        "Drizzle with melted butter (20 g) and serve.",
      ],
      "suggested_seasonings": ["vanilla", "cinnamon"],
    },
  },
  "12b3ccac-44fe-5883-a726-dd3d51880f47": {
    "source": {
      "name": "Kotlety schabowe z kapustą pekińską",
      "description": "Wariacja klasycznego kotleta z lekką surówką.",
      "instructions": [
        "Schab (600 g) przykryj folią spożywczą i rozbij tłuczkiem na plastry grubości ok. 1 cm, dopraw solą i pieprzem z obu stron.",
        "Przygotuj trzy talerze: z mąką, z roztrzepanym jajkiem (1 szt.), z bułką tartą.",
        "Obtocz każdy kotlet kolejno w mące, jajku, na końcu w bułce tartej, dociskając, żeby panierka przylegała.",
        "Rozgrzej olej na patelni, smaż kotlety 3-4 minuty z każdej strony, aż panierka będzie złocista, a mięso w środku białe.",
        "Odsącz kotlety na papierowym ręczniku.",
        "W międzyczasie poszatkuj kapustę pekińską (1 szt.) na cienkie paski, skrop oliwą, dopraw solą i wymieszaj.",
        "Podawaj kotlety z surówką z kapusty pekińskiej.",
      ],
      "suggested_seasonings": ["majeranek", "kminek"],
    },
    "en_GB": {
      "name": "Pork cutlets with Chinese cabbage",
      "description": "A variation on the classic cutlet with a light slaw.",
      "instructions": [
        "Cover the pork loin (600 g) with cling film and flatten with a meat mallet into slices about 1 cm thick. Season both sides with salt and pepper.",
        "Prepare three plates: one with flour, one with beaten egg (1 egg), and one with breadcrumbs.",
        "Coat each cutlet in flour, then egg and finally breadcrumbs, pressing firmly so the coating sticks.",
        "Heat the oil in a frying pan and fry the cutlets for 3-4 minutes on each side until the coating is golden and the meat is white inside.",
        "Drain the cutlets on kitchen paper.",
        "Meanwhile, finely shred the Chinese cabbage (1 cabbage), drizzle with olive oil, season with salt and toss.",
        "Serve the cutlets with the Chinese cabbage slaw.",
      ],
      "suggested_seasonings": ["marjoram", "caraway"],
    },
  },
  "fa0cc5d6-1e39-5db5-bdf0-5d4018f76149": {
    "source": {
      "name": "Makaron z cukinią i parmezanem",
      "description": "Lekki, letni makaron — gotowy w kwadrans.",
      "instructions": [
        "Ugotuj makaron (200 g) w osolonej wodzie według instrukcji na opakowaniu.",
        "Pokrój cukinię (2 szt.) w half-moony, podsmaż na oliwie (20 ml) z czosnkiem 6-8 minut.",
        "Połącz makaron z cukinią, dodaj startowy parmezan (40 g).",
        "Dopraw solą i pieprzem, podawaj od razu.",
      ],
      "suggested_seasonings": ["chili w płatkach", "świeża bazylia"],
    },
    "en_GB": {
      "name": "Courgette and Parmesan pasta",
      "description": "Light, summery pasta — ready in a quarter of an hour.",
      "instructions": [
        "Cook the pasta (200 g) in salted water according to the packet instructions.",
        "Cut the courgettes (2 courgettes) into half-moons and fry in olive oil (20 ml) with garlic for 6-8 minutes.",
        "Combine the pasta with the courgettes and add the grated Parmesan (40 g).",
        "Season with salt and pepper and serve immediately.",
      ],
      "suggested_seasonings": ["chilli flakes", "fresh basil"],
    },
  },
  "aada2940-9574-5b23-a23e-7030f7d2b021": {
    "source": {
      "name": "Risotto z krewetkami",
      "description": "Kremowe risotto z owocami morza.",
      "instructions": [
        "Cebulę (100 g) drobno pokrój.",
        "Rozpuść masło na patelni, podsmaż cebulę 3 minuty, aż zmięknie.",
        "Wsyp ryż i smaż 1-2 minuty mieszając, aż ziarna zrobią się szkliste na brzegach.",
        "Rozpuść bulion (2 kostki) w garnku z gorącą wodą, trzymaj na małym ogniu.",
        "Dolewaj gorący bulion chochlą, ciągle mieszając, czekając aż ryż wchłonie płyn przed dolaniem kolejnej porcji — tak przez ok. 18 minut.",
        "Na ostatnie 4-5 minut gotowania dodaj krewetki (200 g) — są gotowe, gdy zrobią się różowe.",
        "Zdejmij z ognia, dopraw solą i pieprzem, podawaj od razu, dopóki jest kremowe.",
      ],
      "suggested_seasonings": ["natka pietruszki", "chili w płatkach"],
    },
    "en_GB": {
      "name": "Prawn risotto",
      "description": "Creamy seafood risotto.",
      "instructions": [
        "Finely chop the onion (100 g).",
        "Melt the butter in a frying pan and fry the onion for 3 minutes until soft.",
        "Add the rice and fry for 1-2 minutes, stirring, until the edges of the grains turn translucent.",
        "Dissolve the stock (2 cubes) in a saucepan of hot water and keep over a low heat.",
        "Add the hot stock a ladleful at a time, stirring constantly and waiting until each addition is absorbed before adding the next, for about 18 minutes.",
        "For the final 4-5 minutes of cooking, add the prawns (200 g). They are ready when pink.",
        "Remove from the heat, season with salt and pepper, and serve straight away while creamy.",
      ],
      "suggested_seasonings": ["parsley", "chilli flakes"],
    },
  },
  "7760a7bf-c07f-56e8-b1e4-8c59b54fc225": {
    "source": {
      "name": "Kasza gryczana z pieczarkami i cebulą",
      "description":
          "Sycące, wegetariańskie danie w tradycyjnym, polskim stylu.",
      "instructions": [
        "Ugotuj kaszę gryczaną (200 g) według instrukcji na opakowaniu.",
        "Podsmaż cebulę na oleju (20 ml) do zeszklenia, dodaj pokrojone pieczarki (300 g).",
        "Smaż razem 8-10 minut, aż pieczarki się zrumienią.",
        "Wymieszaj z ugotowaną kaszą, dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": ["majeranek", "tymianek"],
    },
    "en_GB": {
      "name": "Buckwheat with mushrooms and onion",
      "description": "A filling vegetarian dish in traditional Polish style.",
      "instructions": [
        "Cook the buckwheat (200 g) according to the packet instructions.",
        "Fry the onion in oil (20 ml) until translucent, then add the sliced mushrooms (300 g).",
        "Fry together for 8-10 minutes until the mushrooms are browned.",
        "Mix with the cooked buckwheat and season with salt and pepper.",
      ],
      "suggested_seasonings": ["marjoram", "thyme"],
    },
  },
  "5725b5c2-eaa5-5f7c-8c64-d4ca428bec52": {
    "source": {
      "name": "Zapiekanka z cukinii i sera",
      "description": "Lekka zapiekanka warzywna z piekarnika.",
      "instructions": [
        "Nagrzej piekarnik do 190°C.",
        "Pokrój cukinię (2 szt.) i pomidory (200 g) w plastry, ułóż naprzemiennie w naczyniu żaroodpornym.",
        "Skrop oliwą (15 ml), dopraw solą, oregano i pieprzem.",
        "Posyp startą mozzarellą i piecz 25-30 minut, aż ser się zarumieni.",
      ],
      "suggested_seasonings": ["oregano", "bazylia"],
    },
    "en_GB": {
      "name": "Courgette and cheese bake",
      "description": "A light oven-baked vegetable dish.",
      "instructions": [
        "Preheat the oven to 190°C.",
        "Slice the courgettes (2 courgettes) and tomatoes (200 g), then arrange alternating slices in an ovenproof dish.",
        "Drizzle with olive oil (15 ml) and season with salt, oregano and pepper.",
        "Sprinkle with grated mozzarella and bake for 25-30 minutes until the cheese is golden.",
      ],
      "suggested_seasonings": ["oregano", "basil"],
    },
  },
  "1b91ab9f-7b8d-5caf-aac4-a8a73b6007b2": {
    "source": {
      "name": "Bakłażan zapiekany po grecku",
      "description": "Aromatyczny, roślinny obiad w śródziemnomorskim stylu.",
      "instructions": [
        "Nagrzej piekarnik do 200°C (góra-dół, bez termoobiegu, jeśli to możliwe).",
        "Bakłażana (1 szt.) pokrój w plastry grubości ok. 1 cm.",
        "Ułóż plastry na blasze wyłożonej papierem do pieczenia, skrop oliwą z obu stron.",
        "Piecz 15 minut, aż plastry zaczną się lekko rumienić na brzegach.",
        "Wyjmij blachę, polej plastry pomidorami krojonymi (400 g), dopraw oregano (3 g), solą i pieprzem.",
        "Posyp pokruszoną fetą (100 g) po wierzchu.",
        "Piecz jeszcze 10 minut, aż feta się zarumieni, a bakłażan będzie miękki (sprawdź widelcem). Podawaj od razu.",
      ],
      "suggested_seasonings": ["oregano", "cynamon (szczypta, po grecku)"],
    },
    "en_GB": {
      "name": "Greek-style baked aubergine",
      "description":
          "A fragrant, plant-based lunch with Mediterranean flavours.",
      "instructions": [
        "Preheat the oven to 200°C, using top and bottom heat without the fan if possible.",
        "Cut the aubergine (1 aubergine) into slices about 1 cm thick.",
        "Arrange on a lined baking tray and drizzle both sides with olive oil.",
        "Bake for 15 minutes until the edges start to colour lightly.",
        "Remove the tray, spoon the chopped tomatoes (400 g) over the slices and season with oregano (3 g), salt and pepper.",
        "Sprinkle the crumbled feta (100 g) over the top.",
        "Bake for another 10 minutes until the feta is golden and the aubergine is soft when tested with a fork. Serve immediately.",
      ],
      "suggested_seasonings": ["oregano", "cinnamon (a pinch, Greek style)"],
    },
  },
  "7149e822-7654-59c8-a8e3-81890685533f": {
    "source": {
      "name": "Sałatka z tuńczykiem i jajkiem",
      "description": "Lekka, białkowa kolacja gotowa w 15 minut.",
      "instructions": [
        "Ugotuj jajka (3 szt.) na twardo, ostudź, obierz i pokrój.",
        "Porwij sałatę (0,3 szt.), pokrój pomidory (150 g).",
        "Wymieszaj wszystkie składniki z odsączonym tuńczykiem (150 g).",
        "Skrop oliwą (15 ml), dopraw solą i pieprzem.",
      ],
      "suggested_seasonings": ["koperek", "szczypiorek"],
    },
    "en_GB": {
      "name": "Tuna and egg salad",
      "description": "A light, protein-rich supper ready in 15 minutes.",
      "instructions": [
        "Hard-boil the eggs (3 eggs), then cool, peel and slice.",
        "Tear the lettuce (0.3 lettuce) and chop the tomatoes (150 g).",
        "Mix all the ingredients with the drained tuna (150 g).",
        "Drizzle with olive oil (15 ml) and season with salt and pepper.",
      ],
      "suggested_seasonings": ["dill", "chives"],
    },
  },
  "be56627e-b725-549a-812e-03e9e2f31e30": {
    "source": {
      "name": "Kanapki caprese",
      "description":
          "Włoska klasyka na kanapce — pomidor, mozzarella, bazylia.",
      "instructions": [
        "Pokrój chleb (120 g), mozzarellę (125 g) i pomidory (200 g) w plastry.",
        "Ułóż na chlebie na przemian ser i pomidory.",
        "Skrop oliwą (15 ml), posyp bazylią (1 g) i solą.",
      ],
      "suggested_seasonings": ["świeża bazylia", "oregano"],
    },
    "en_GB": {
      "name": "Caprese sandwiches",
      "description":
          "An Italian classic in a sandwich — tomato, mozzarella and basil.",
      "instructions": [
        "Slice the bread (120 g), mozzarella (125 g) and tomatoes (200 g).",
        "Arrange alternating slices of cheese and tomato on the bread.",
        "Drizzle with olive oil (15 ml) and sprinkle with basil (1 g) and salt.",
      ],
      "suggested_seasonings": ["fresh basil", "oregano"],
    },
  },
  "1c821110-1d90-5e44-825b-bd77a2e6ba2e": {
    "source": {
      "name": "Sałatka caprese",
      "description": "Prosta, elegancka sałatka na ciepłe wieczory.",
      "instructions": [
        "Pokrój pomidory (300 g) i mozzarellę w plastry.",
        "Ułóż na talerzu naprzemiennie.",
        "Skrop oliwą (20 ml) i octem balsamicznym, posyp bazylią (2 g), solą i pieprzem.",
      ],
      "suggested_seasonings": ["świeża bazylia", "oregano"],
    },
    "en_GB": {
      "name": "Caprese salad",
      "description": "A simple, elegant salad for warm evenings.",
      "instructions": [
        "Slice the tomatoes (300 g) and mozzarella.",
        "Arrange alternating slices on a plate.",
        "Drizzle with olive oil (20 ml) and balsamic vinegar, then sprinkle with basil (2 g), salt and pepper.",
      ],
      "suggested_seasonings": ["fresh basil", "oregano"],
    },
  },
  "ec67eb34-af7b-50b4-88d3-6e8cdd2713b2": {
    "source": {
      "name": "Omlet na słono z serem i szczypiorkiem",
      "description": "Prosta, szybka kolacja na słono.",
      "instructions": [
        "Roztrzep jajka (3 szt.) z solą i pieprzem.",
        "Rozgrzej masło (10 g) na patelni, wlej jajka, smaż na małym ogniu pod przykryciem.",
        "Posyp startym serem, złóż na pół, gdy omlet się zetnie.",
      ],
      "suggested_seasonings": ["papryka słodka"],
    },
    "en_GB": {
      "name": "Savoury cheese and chive omelette",
      "description": "A simple, quick savoury supper.",
      "instructions": [
        "Beat the eggs (3 eggs) with salt and pepper.",
        "Heat the butter (10 g) in a frying pan, pour in the eggs and cook, covered, over a low heat.",
        "Sprinkle with grated cheese and fold in half once set.",
      ],
      "suggested_seasonings": ["sweet paprika"],
    },
  },
  "95b35fc0-3ab0-5e4d-9453-5f20724ea012": {
    "source": {
      "name": "Tost z hummusem i warzywami",
      "description": "Roślinna, lekka kolacja gotowa w kilka minut.",
      "instructions": [
        "Opiecz kromki chleba (80 g).",
        "Posmaruj hummusem (60 g).",
        "Ułóż na wierzchu plasterki papryki (0,3 szt.) i ogórka.",
      ],
      "suggested_seasonings": ["kmin rzymski", "papryka wędzona"],
    },
    "en_GB": {
      "name": "Hummus and vegetable toast",
      "description": "A light, plant-based supper ready in a few minutes.",
      "instructions": [
        "Toast the bread slices (80 g).",
        "Spread with hummus (60 g).",
        "Top with slices of pepper (0.3 pepper) and cucumber.",
      ],
      "suggested_seasonings": ["cumin", "smoked paprika"],
    },
  },
  "9c05677e-a735-56ab-a085-5507e041567e": {
    "source": {
      "name": "Sałatka z soczewicy i fety",
      "description": "Sycąca, roślinna sałatka na kolację.",
      "instructions": [
