  "6fa98cd6-f081-53aa-9a67-2ab63be67bc1": {
    "source": {
      "name": "Kanapki z pastą z ciecierzycy",
      "description": "Roślinna pasta kanapkowa — sycąca i pełna błonnika.",
      "instructions": [
